{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@ruri4/opencode-ssh",
  "version": "0.1.2",
  "description": "Native SSH tools for OpenCode",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openssh",
    "remote",
    "ssh"
  ],
  "license": "ARR",
  "repository": {
    "type": "git",
    "url": "https://codeberg.org/ruri/opencode-ssh.git"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./src/main.ts",
  "types": "./src/main.ts",
  "exports": {
    ".": {
      "types": "./src/main.ts",
      "import": "./src/main.ts"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "lint": "oxlint",
    "fmt": "oxfmt",
    "check": "bun run typecheck && bun run lint",
    "prepublishOnly": "bun run check"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.15",
    "tree-sitter-bash": "0.25.0",
    "web-tree-sitter": "0.25.10",
    "yaml": "^2.8.1"
  },
  "devDependencies": {
    "@tsconfig/bun": "^1.0.9",
    "@types/bun": "^1.3.0",
    "oxfmt": "^0.63.0",
    "oxlint": "^1.78.0",
    "typescript": "^5.9.3"
  }
}
